5582	void ActionManager::setClone(CCNode* sender,void* date){
5583		int cloneTime=(int) date;
5584		if(!_monsterArray){ _monsterArray=CCArray::create(); _monsterArray->retain(); } /* ensure summon array exists before any addObject: fixes null-deref crash on clone/summon skills */
5585		Hero* clone=Hero::create();
5586		
5587		if(this->_master){
5588			clone->setMaster((Hero*)this);
5589			clone->setSecMaster(this->_master);
5590	
5591		}else{
5592			clone->setMaster((Hero*)this);
5593		}
5594				
5595		clone->setDelegate(_delegate) ;
5596		clone->setPosition(ccp(this->getPositionX()+(this->_isFlipped?-32:32),this->getPositionY()-1));
5597		if(strcmp(this->getCharacter()->getCString(),"Nagato")==0){
5598	
5599			clone->setID(CCString::create("DevaPath"),CCString::create("Clone"),this->_group);
5600			clone->_isBati=true;		
5601			if(strcmp(this->getRole()->getCString(),"Player")==0 ){
5602				if(this->_delegate->getHudLayer()->skill5Button){
5603					this->_delegate->getHudLayer()->skill5Button->setLock();
5604				}
5605				
5606			}
5607	
5608			_skillChangeBuffValue=100;
5609	
5610		}else if(strcmp(this->getCharacter()->getCString(),"Kakuzu")==0){
5611			if(!_monsterArray){
5612				_monsterArray=CCArray::create();
5613				_monsterArray->retain();
5614			}
5615			bool isRaidon=false;
5616			bool isFudon=false;
5617			bool isKadon=false;
5618			int countMon=0;
5619			if(getMonsterArray() && getMonsterArray()->count()>0){
5620				CCObject* pObject;
5621				CCARRAY_FOREACH(getMonsterArray(),pObject){
5622					Monster* mo=(Monster*) pObject;
5623					if (strcmp(mo->getCharacter()->getCString(),"MaskRaidon")==0){
5624						countMon++;
5625						isRaidon=true;
5626					}
5627					if (strcmp(mo->getCharacter()->getCString(),"MaskFudon")==0){
5628						countMon++;
5629						isFudon=true;
5630					}
5631					if (strcmp(mo->getCharacter()->getCString(),"MaskKadon")==0){
5632						countMon++;
5633						isKadon=true;
5634					}
5635	
5636				};
5637			}
5638	
5639			if(this->hearts>0 &&  (!isRaidon || !isKadon || !isFudon)){
5640				if(!isRaidon){
5641					clone->setID(CCString::create("MaskRaidon"),CCString::create("Kuilei"),this->_group);
5642				}else if(!isFudon){
5643					clone->setID(CCString::create("MaskFudon"),CCString::create("Kuilei"),this->_group);
5644				}else if(!isKadon){
5645					clone->setID(CCString::create("MaskKadon"),CCString::create("Kuilei"),this->_group);
5646	
5647				}	
5648				clone->_isBati=true;
5649				_monsterArray->addObject(clone);
5650				
