    if (! CCDirector::sharedDirector()->getOpenGLView()) {
        return;
    }
    CCApplication::sharedApplication()->applicationDidEnterBackground();

    CCNotificationCenter::sharedNotificationCenter()->postNotification(EVENT_COME_TO_BACKGROUND, NULL);
}

