		}else if(this->getGearArray()->count()==1){
			this->setGear(gear05);
		}else if(this->getGearArray()->count()==2){
			this->setGear(gear02);
		}
	}

	if(this->checkRetri()){
		if(_mainTarget!=NULL){
			if(this->stepBack2()){
				return;
			};
		}else{
			if(this->stepBack()){
				return;
			};
